return [
  {
    json: {
      mensaje: 'Hola, llevamos 2 días sin poder exportar los informes de ventas a Excel desde la plataforma. Es urgente porque tenemos la junta directiva mañana a primera hora.',
      remitente: 'director.financiero@cliente-corp.com'
    }
  },
  {
    json: {
      mensaje: 'Buenos días, quisiéramos consultar si disponen de descuentos por volumen para una suscripción de 50 usuarios.',
      remitente: 'compras@innovagroup.es'
    }
  },
  {
    json: {
      mensaje: 'El cobro de la factura de este mes vino duplicado en la tarjeta de crédito. Por favor revisar y emitir abono.',
      remitente: 'pagos@startup.io'
    }
  }
];

// ==========================================================================
// Immersive Office - Procesamiento y Estructuración de Respuesta IA Local
// ==========================================================================
const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const inputItem = items[i];
  let rawResponse = inputItem.json?.response || "";
  let aiAnalysis = null;
  let fallbackUsed = false;

  // Intentar parsear el JSON retornado por Ollama
  try {
    if (typeof rawResponse === 'string' && rawResponse.trim().length > 0) {
      const cleaned = rawResponse.replace(/```json/g, '').replace(/```/g, '').trim();
      aiAnalysis = JSON.parse(cleaned);
    } else if (typeof rawResponse === 'object' && rawResponse !== null && (rawResponse.categoria || rawResponse.urgencia)) {
      aiAnalysis = rawResponse;
    }
  } catch (e) {
    aiAnalysis = null;
  }

  // Si Ollama no está activo o hubo error, usamos fallback de simulación para tests inmediatos
  if (!aiAnalysis) {
    fallbackUsed = true;
    let userMsg = inputItem.json?.mensaje || inputItem.json?.body?.mensaje || "";
    if (!userMsg) {
      try {
        userMsg = $('Casos de Prueba (Tickets Mock)').all()[i]?.json?.mensaje || $('Webhook Ticket').first()?.json?.body?.mensaje || "";
      } catch (e) {
        userMsg = "Consulta de soporte general";
      }
    }

    const msgLower = userMsg.toLowerCase();
    let cat = "Soporte Técnico";
    let urg = "Media";
    let sent = "Neutro";
    let action = "Revisar ticket en cola estándar.";

    if (msgLower.includes('factura') || msgLower.includes('cobro') || msgLower.includes('abono')) {
      cat = "Facturación";
      urg = "Alta";
      sent = "Negativo";
      action = "Verificar pasarela de pagos y emitir rectificación si procede.";
    } else if (msgLower.includes('descuento') || msgLower.includes('comprar') || msgLower.includes('suscripción') || msgLower.includes('precio') || msgLower.includes('usuarios')) {
      cat = "Ventas";
      urg = "Baja";
      sent = "Positivo";
      action = "Asignar a ejecutivo de cuentas comerciales.";
    } else if (msgLower.includes('urgente') || msgLower.includes('caído') || msgLower.includes('junta') || msgLower.includes('bloqueo')) {
      cat = "Soporte Técnico";
      urg = "Crítica";
      sent = "Frustrado";
      action = "Escalar a ingeniería L2 de inmediato y notificar al cliente.";
    }

    aiAnalysis = {
      categoria: cat,
      urgencia: urg,
      sentimiento: sent,
      resumen_breve: userMsg.slice(0, 60) + "...",
      accion_sugerida: action,
      aviso: "Respuesta generada por fallback de simulación. (Para IA real con Ollama: 'ollama run llama3.2')"
    };
  }

  results.push({
    json: {
      ticket_id: "TCK-" + Math.floor(1000 + Math.random() * 9000),
      remitente: inputItem.json?.remitente || inputItem.json?.body?.remitente || "cliente@corp.com",
      fecha_recepcion: new Date().toISOString(),
      clasificacion_ia: aiAnalysis,
      modo_ejecucion: fallbackUsed ? "Modo Simulación / Fallback" : "Ollama Local LLM Activo",
      tiempo_respuesta_modelo_ms: inputItem.json?.total_duration ? Math.round(inputItem.json.total_duration / 1000000) : null,
      fuente: "immersiveoffice.online"
    }
  });
}

return results;

// Monta la peticion a Ollama. Se hace aqui y no en una expresion del nodo HTTP
// porque el prompt lleva comillas simples y saltos de linea que rompen la
// expresion y dejan el "JSON Body" invalido.
const instrucciones = [
  'Eres un clasificador experto de tickets de soporte empresarial.',
  'Responde UNICAMENTE con un objeto JSON, sin texto adicional ni markdown.',
  '',
  'Campos obligatorios:',
  '- categoria: uno de "Soporte Tecnico", "Facturacion", "Ventas", "Reclamacion"',
  '- urgencia: uno de "Baja", "Media", "Alta", "Critica"',
  '- sentimiento: uno de "Positivo", "Neutro", "Negativo", "Frustrado"',
  '- resumen_breve: menos de 12 palabras',
  '- accion_sugerida: siguiente paso para el agente de soporte',
  '',
  'Mensaje del cliente: ',
].join('\n');

return $input.all().map(item => {
  const j = item.json;
  const mensaje = (j.body && j.body.mensaje) || (j.query && j.query.mensaje) || j.mensaje || 'Sin mensaje';
  return { json: {
    ...j,
    mensaje,
    payload: {
      model: 'llama3.2:1b',
      stream: false,
      format: 'json',
      prompt: instrucciones + mensaje,
      options: { temperature: 0.2 },
    },
  }};
});
